from common import *
import shutil,platform,importlib.metadata,datetime
def main():
 assert not BASE.exists()
 import pandas as pd,numpy,lightgbm,qlib
 from backtest.scripts.register.experiment_registry import load_registry
 rows={r['exp_id']:r for r in load_registry(ROOT/'backtest/experiments/registry.jsonl')}
 assert rows[BASELINE_ID]['current_baseline'] is True
 for old in [PREVIOUS,ROOT/'backtest/experiments/models/training-target/quantile-n-p50-20261107-v1']:
  r=subprocess.run([sys.executable,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py'),'status','--state',str(old/'docs/harness-state.json')],capture_output=True,text=True,cwd=ROOT);assert r.returncode==0 and json.loads(r.stdout)['status']=='closed'
 assert Path(qlib.__file__).resolve().is_relative_to(ROOT)
 qlib.init(provider_uri=str(PROVIDER),region='cn',kernels=1)
 from qlib.data import D
 version=str(pd.Timestamp(D.calendar(start_time='2020-01-01')[-1]).date());assert version=='2026-11-03'
 for p in ['configs','docs','data','metrics','reports']:(BASE/p).mkdir(parents=True)
 shutil.copyfile(PREVIOUS/'configs/evaluation.yaml',BASE/'configs/evaluation.yaml')
 prior=read(PREVIOUS/'configs/frozen-study.json');encoding=read(PREVIOUS/'configs/prepared-inputs.json')['variants']['quantile10']
 study={'user_request':'1.Hn标签等于H1到Hn原始累计收益之和，先做H20，不分档和10档。2.H7/H15做10档，与H20比较分风格，检验T减弱D增强是否普遍。','confirmed_formula':'sum(k=1..20)[Ref(close,-(k+1))/Ref(close,-1)-1]','hypothesis':'Summing within-horizon cumulative returns rewards earlier/persistent gains; may favor smoother paths but does not mathematically penalize volatility. Test predictive changes separately from this mechanism. Quantization may interact with label horizon and market style.','formal_baseline':BASELINE_ID,'candidates':[{'id':v,'horizon':HORIZONS[v],'target':'path_sum' if v.startswith('sum') else 'terminal_return','bins':None if v=='sum20continuous' else 10} for v in VARIANTS],'seeds':SEEDS,'parameters':prior['parameters'],'train_window':['2004-01-02','2020-07-31'],'eval_window':['2020-08-03','2026-07-31'],'es_metric':'top5_h5_net_ann','valid_cutoff':'2026-07-23','data_version':version,'source_policy':{'features':'Nov2 existing frozen feature blocks','labels':'Nov3 frozen provider and original H7/H15/H20 labels; controls must match ordered inputs','validation':'Existing exit-bounded H5 valid and tradable, same as p50 trials','inference':'Formal DK_I on Nov3 provider; exact control prediction bridge','v5_reference':'Current v5 uses old H20 labels; compare against it as formal baseline, but scientific paired H20 controls use existing Nov3 continuous and q10 models. Do not attribute old/new differences to grading.'},'label_processing':{'base':'Legacy H40-valid/listing-qualified base; each target keeps its own finite mask. Do not force an all-H intersection.','sum':'Float64 sum of 20 raw float32 cumulative returns, require every component finite; CSRankNorm (average daily pct rank-.5)*3.46 after target mask, before training-date selection.','continuous':'CSRankNorm without grading','quantile10':'Exact rational midpoint ranks; right-closed boundaries j/10; preserve ties; apply fixed v5 affine and no reranking','affine':{k:encoding[k] for k in ['scale','offset','target_mean','target_std']}},'comparison_rule':{'H_ranking':'Among H7/H15/H20, list all maximizers separately in each D/F/T for net_ann and Sharpe, before and after q10. Historical seven-H conclusions are context, not a new seven-H sweep.','universal':'For each H compute q10 minus same-source continuous. T deterioration requires all three net_ann differences < -1e-12; D improvement all three >1e-12. Report counts, every difference, Sharpe separately, and per-seed/year consistency. No claim beyond tested three H.','path_sum':'Compare sum20continuous vs original H20continuous, sum20q10 vs original H20q10, and within sum20 q10 vs continuous; separate returns/Sharpe/RankIC.','mechanism':'Train-only relation between path-sum rank and realized path volatility conditional on daily terminal-return deciles; illustrative equal-terminal paths to show no guaranteed lower-volatility preference. Descriptive, not a selection criterion.','limitations':'Historical selection window; F only136days/seven2024months; no independent OOS and no automatic promotion.'},'budget':{'nominal_new_fits':20,'max_model_fits':22,'max_wall_hours':10,'concurrency':1,'closeout_reserve_seconds':2700,'estimated_total_hours':[4,5]},'prior_cumulative_model_fits':PRIOR_FITS,'run_priority':VARIANTS,'representative':REPRESENTATIVE,'entry_policy':'One model study entry; four internal candidates plus reused controls. Native parent lifecycle and actual fit ledger; supplementary candidate/report ledger maintains four distinct identities and scientific results. Representative sum20q10 predeclared, not selected winner.','temporary_directory':str(TMP),'implementation_steps':['Verify control models/predictions/input hashes and provider version.','Materialize labels with finite-mask/quantile/formula tests; no outcome exposure.','Fit four fixed groups, five seeds each, sequential; capture every ES round/ties.','Formal annual DK_I inference, exact control bridge; canonical Top3H5 all/year/style and H5 RankIC.','Register every completed/failed candidate through one parent with individual receipts, rebuild reports before next group.','Review input/scientific claims, cleanup exact task-owned temporary data, official platform dry-run, native close.']}
 write(BASE/'configs/frozen-study.json',study)
 meta={'schema_version':2,'entity_type':'experiment','kind':'model','track':'all_a','exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'experiment_type':'training_target','title':'累计路径收益与10档期限对照 · patience50','change_summary':'H20路径累计收益和连续/10档；H7/H15终点收益10档；同源H7/H15/H20分风格成对对照。','comparison_baseline':{'ref':BASELINE_ID,'version':'v5'},'activity':'model_research','role':'experiment','changed_axes':['label_path_aggregation','label_quantization','label_horizon'],'inventory_kind':'asset_snapshot'}
 write(BASE/'metadata.json',meta)
 env={'python':sys.version,'executable':sys.executable,'platform':platform.platform(),'git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'initial_git_status':subprocess.check_output(['git','status','--short'],cwd=ROOT,text=True),'packages':{n:importlib.metadata.version(n) for n in ['numpy','pandas','lightgbm','scipy','pyqlib']}}
 write(BASE/'docs/environment.json',env)
 files=[FEATURE,OLD_LABEL,VALID,DATES,WEIGHTS,PRIOR/'docs/prepared-labels.json',PREVIOUS/'configs/prepared-inputs.json',PREVIOUS/'docs/provider-inputs.json.gz',PROVIDER/'calendars/day.txt',PROVIDER.parent/'st_daily.csv',CURRENT/'configs/model-manifest.json',CURRENT/'metrics/model-evaluation.json',PREVIOUS/'metrics/quantile10-new.json']
 for h in [7,15,20]:
  proof=PRIOR/'docs'/f'sources-h{h}.json';files += [proof,PRIOR/'docs'/f'inputs-h{h}.json',PRIOR/'metrics'/f'h{h}-model.json']
  for c in read(proof)['components']:
   for k in ['model','training']:check(c[k]);files.append(ROOT/c[k]['path'])
   pred=ROOT/f'backtest/result/20261105_horizon_p50/h{h}'/f'{c["session"]}_pred.pkl';assert pred.is_file();files.append(pred)
  for b in read(PRIOR/'docs/prepared-labels.json')['horizons'][str(h)]['blocks']:check(b);files.append(ROOT/b['path'])
 for tag in ['new','old']:
  p=PREVIOUS/'docs'/f'predictions-quantile10-{tag}.json';files.append(p)
  for c in read(p)['components']:
   for k in ['model','prediction','training']:check(c[k]);files.append(ROOT/c[k]['path'])
  check(read(p)['ensemble']);files.append(ROOT/read(p)['ensemble']['path'])
 for name in ['common','setup','bootstrap']:save_source(TMP/(name+'.py'))
 files += [BASE/'configs/frozen-study.json',BASE/'configs/evaluation.yaml',BASE/'docs/environment.json',BASE/'docs/adapter-common.json',ROOT/'backtest/models/regime_adapt.py',ROOT/'backtest/models/rankic_early_stop.py',ROOT/'backtest/scripts/train/train_regime_arm.py',ROOT/'backtest/scripts/evaluate/eval_ic_multi_pool.py',ROOT/'backtest/scripts/evaluate/ensemble_preds.py']
 plan={'schema_version':2,'campaign_id':'pathsum-quantile10-p50-20261107-v1','idea':study['user_request'],'track':'all_a_model','direction':'training-target','anchor_exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'baseline_ref':BASELINE_ID,'allowed_changes':['training_label_recipe'],'selection_rule':json.dumps(study['comparison_rule'],ensure_ascii=False),'data_version':version,'inputs':[str(p) for p in dict.fromkeys(files)],'seeds':SEEDS,'budget':{'max_rounds':1,'max_variants':4,'max_attempts_per_variant':2,'max_wall_hours':10,'max_no_new_evidence_rounds':1,'concurrency':1},'execution_budget':{'max_model_fits':22,'new_label_horizons':[7,15,20]},'scientific_candidate_count':4,'temporary_directory':str(TMP),'known_native_scope_gap':study['entry_policy'],'prior_cumulative_model_fits':PRIOR_FITS}
 write(BASE/'configs/harness-plan.json',plan)
 r=subprocess.run([sys.executable,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py'),'init','--plan',str(BASE/'configs/harness-plan.json')],capture_output=True,text=True,cwd=ROOT);assert r.returncode==0,r.stdout+r.stderr
 write(PROGRESS,{'status':'preparing','scientific_candidates':{v:{'status':'planned','treatments':{}} for v in VARIANTS},'prior_fit_count':PRIOR_FITS,'jobs':[],'frozen_study':fingerprint(BASE/'configs/frozen-study.json'),'reused_controls':REUSED})
 print(json.dumps({'archive':str(BASE),'deadline_local':datetime.datetime.fromtimestamp(read(STATE)['deadline']).isoformat(),'nominal_fits':20},ensure_ascii=False),flush=True)
if __name__=='__main__':main()
